1	// How a scenario unfolds. This module knows the order events happen in and
2	// what each step leaves behind for the next one; it delegates what a policy
3	// costs to pricing.ts and what it pays out to coverage.ts.
4	
5	import { premiumFor, type Customer, type Item } from "./pricing.js";
6	import {
7	  capFor,
8	  payoutForDamages,
9	  settleClaim,
10	  type Damage,
11	} from "./coverage.js";
12	
13	export type { Customer, KnownItemType } from "./pricing.js";
14	export type { Damage } from "./coverage.js";
15	
16	export interface Scenario {
17	  customer: Customer;
18	  steps: Step[];
19	}
20	
21	export interface QuoteStep {
22	  op: "quote";
23	  items: Item[];
24	}
25	
26	export interface ClaimStep {
27	  op: "claim";
28	  policy: number;
29	  incident: { cause: string; damages: Damage[] };
30	}
31	
32	export type Step = QuoteStep | ClaimStep;
33	
34	export interface ScenarioResults {
35	  results: ({ premium: number } | { payout: number; remainingCap: number })[];
36	}
37	
38	// What earlier steps have established by the time a later step is priced.
39	// Steps are not independent: a quote is a follow-up contract when the customer
40	// already took a quote earlier in the same scenario. Folding this forward —
41	// rather than re-deriving it from the step prefix — is what lets a step read
42	// the state its predecessors left behind.
43	interface Policy {
44	  // The insured items, kept because a claim is settled against them: what a
45	  // damage reimburses depends on the item's own material and enchantment, not
46	  // on the damage entry alone.
47	  items: Item[];
48	  remainingCap: number;
49	}
50	
51	interface ScenarioState {
52	  hasQuoted: boolean;
53	  // Keyed by the step index of the quote that created the policy, which is
54	  // how a later claim step refers to it.
55	  policies: Map<number, Policy>;
56	}
57	
58	const INITIAL_STATE: ScenarioState = { hasQuoted: false, policies: new Map() };
59	
60	type StepOutcome = ScenarioResults["results"][number];
61	
62	interface StepRun {
63	  outcome: StepOutcome;
64	  state: ScenarioState;
65	}
66	
67	// Every policy a step establishes is recorded the same way, so both handlers
68	// go through here rather than each rebuilding the map.
69	const withPolicy = (
70	  state: ScenarioState,
71	  index: number,
72	  policy: Policy,
73	): ScenarioState => ({
74	  ...state,
75	  policies: new Map(state.policies).set(index, policy),
76	});
77	
78	const runQuote = (
79	  { items }: QuoteStep,
80	  customer: Customer,
81	  state: ScenarioState,
82	  index: number,
83	): StepRun => ({
84	  outcome: {
85	    premium: premiumFor(items, {
86	      customer,
87	      isFollowUpContract: state.hasQuoted,
88	    }),
89	  },
90	  state: withPolicy({ ...state, hasQuoted: true }, index, {
91	    items,
92	    remainingCap: capFor(items),
93	  }),
94	});
95	
96	const runClaim = (
97	  { policy: policyIndex, incident }: ClaimStep,
98	  state: ScenarioState,
99	): StepRun => {
100	  // A claim always names a policy an earlier quote step created. No spec
101	  // example covers a claim naming a step that never quoted, so this is not the
102	  // considered answer to that question — but the previous fallback of an empty
103	  // policy was worse than none: it returned a payout of 0 with 0 cap left,
104	  // which is indistinguishable from a real policy that has exhausted its cap.
105	  // A typo'd index read as a legitimate settlement. Fail loudly instead until
106	  // an example says otherwise.
107	  const policy = state.policies.get(policyIndex);
108	  if (policy === undefined) {
109	    throw new Error(`claim names policy ${policyIndex}, which no step created`);
110	  }
111	  const { payout, remainingCap } = settleClaim(
112	    payoutForDamages(policy.items, incident.damages),
113	    policy.remainingCap,
114	  );
115	
116	  return {
117	    outcome: { payout, remainingCap },
118	    state: withPolicy(state, policyIndex, { ...policy, remainingCap }),
119	  };
120	};
121	
122	// Dispatches a step to its handler. Written as an exhaustive switch on `op`
123	// so that adding a step kind to the Step union turns "I forgot to handle it"
124	// into a compile error rather than a wrong number.
125	const runStep = (
126	  step: Step,
127	  customer: Customer,
128	  state: ScenarioState,
129	  index: number,
130	): StepRun => {
131	  switch (step.op) {
132	    case "quote":
133	      return runQuote(step, customer, state, index);
134	    case "claim":
135	      return runClaim(step, state);
136	  }
137	};
138	
139	export const runScenario = ({ customer, steps }: Scenario): ScenarioResults => {
140	  const { results } = steps.reduce<{
141	    results: StepOutcome[];
142	    state: ScenarioState;
143	  }>(
144	    ({ results, state }, step, index) => {
145	      const stepRun = runStep(step, customer, state, index);
146	      return { results: [...results, stepRun.outcome], state: stepRun.state };
147	    },
148	    { results: [], state: INITIAL_STATE },
149	  );
150	
151	  return { results };
152	};
