1	// What a policy costs. This module answers one question — given the items on
2	// a policy and the context the policy is written in, what premium does the
3	// customer pay? It knows nothing about scenarios, steps, or the order events
4	// happen in; see claim-office.ts for that. What a policy pays OUT is the
5	// mirror question, answered by coverage.ts.
6	
7	import { roundUpInFavourOfMHPCO } from "./rounding.js";
8	
9	export interface Customer {
10	  yearsWithMHPCO: number;
11	}
12	
13	const PROCESSING_FEE = 5;
14	const BASE_PREMIUM_BY_TYPE = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	  potion: 40,
19	  rune: 25,
20	  moonstone: 25,
21	} as const satisfies Record<string, number>;
22	
23	export type KnownItemType = keyof typeof BASE_PREMIUM_BY_TYPE;
24	
25	export interface Item {
26	  type: KnownItemType;
27	  material?: string;
28	  enchantment?: number;
29	  cursed?: boolean;
30	}
31	
32	const FIRST_INSURANCE_SURCHARGE = 0.1;
33	
34	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
35	
36	const BLOCK_SIZE = 3;
37	const BLOCK_BASE_PREMIUM = 60;
38	
39	const groupByType = (items: Item[]): Item[][] => [
40	  ...items
41	    .reduce(
42	      (groups, item) =>
43	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
44	      new Map<KnownItemType, Item[]>(),
45	    )
46	    .values(),
47	];
48	
49	const sumOfBasePremiums = (items: Item[]): number =>
50	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
51	
52	// Exactly three alike components form a block at a reduced premium; any
53	// other count is priced per item.
54	//
55	// Deliberate simplification: "component" is not yet enforced, so three alike
56	// swords would also get the block. No test covers it and the spec gives no
57	// example — revisit when one does.
58	const groupBasePremiumOf = (group: Item[]): number =>
59	  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(group);
60	
61	const policyBasePremiumOf = (items: Item[]): number =>
62	  groupByType(items).reduce((sum, group) => sum + groupBasePremiumOf(group), 0);
63	
64	const CURSE_SURCHARGE = 0.5;
65	
66	// Item-specific modifiers are charged as a percentage of the affected item's
67	// OWN base premium. See withPolicyWideModifiers for the other scope.
68	const shareOfOwnBasePremium = (item: Item, rate: number): number =>
69	  basePremiumOf(item) * rate;
70	
71	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
72	const HIGH_ENCHANTMENT_THRESHOLD = 5;
73	
74	const isHighlyEnchanted = (item: Item): boolean =>
75	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
76	
77	const ITEM_SURCHARGES: { applies: (item: Item) => boolean; rate: number }[] = [
78	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
79	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE },
80	];
81	
82	// Every modifier rate in this domain combines additively, whether item-scoped
83	// or policy-wide: two rates of +50 % and +30 % make +80 %, never +95 %.
84	const combinedRate = (rates: number[]): number =>
85	  rates.reduce((total, rate) => total + rate, 0);
86	
87	// Both item modifiers can apply at once, and they stack additively: a cursed
88	// item with enchantment 5 pays 50 % + 30 % of its base premium.
89	const surchargeRateOn = (item: Item): number =>
90	  combinedRate(
91	    ITEM_SURCHARGES.filter(({ applies }) => applies(item)).map(
92	      ({ rate }) => rate,
93	    ),
94	  );
95	
96	const surchargeOn = (item: Item): number =>
97	  shareOfOwnBasePremium(item, surchargeRateOn(item));
98	
99	const itemSurchargesOf = (items: Item[]): number =>
100	  items.reduce((sum, item) => sum + surchargeOn(item), 0);
101	
102	// Policy-wide modifiers scale the whole policy base premium, unlike item
103	// modifiers which are charged against the affected item's own base premium.
104	// They combine additively, so a policy carrying +10 % and -20 % pays 90 % of
105	// its base — not 110 % × 80 %.
106	const LOYALTY_DISCOUNT = -0.2;
107	const LOYALTY_THRESHOLD_YEARS = 2;
108	
109	const isLoyal = (customer: Customer): boolean =>
110	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
111	
112	const FOLLOW_UP_CONTRACT_DISCOUNT = -0.15;
113	
114	// Everything about the policy's context that shifts its rates, as opposed to
115	// the items being priced. Travels as one value because every policy-wide
116	// modifier reads from it.
117	export interface PolicyContext {
118	  customer: Customer;
119	  isFollowUpContract: boolean;
120	}
121	
122	const policyWideModifierRatesFor = ({
123	  customer,
124	  isFollowUpContract,
125	}: PolicyContext): number[] => [
126	  FIRST_INSURANCE_SURCHARGE,
127	  ...(isLoyal(customer) ? [LOYALTY_DISCOUNT] : []),
128	  ...(isFollowUpContract ? [FOLLOW_UP_CONTRACT_DISCOUNT] : []),
129	];
130	
131	const withPolicyWideModifiers = (
132	  policyBase: number,
133	  policy: PolicyContext,
134	): number =>
135	  policyBase * (1 + combinedRate(policyWideModifierRatesFor(policy)));
136	
137	export const premiumFor = (items: Item[], policy: PolicyContext): number =>
138	  roundUpInFavourOfMHPCO(
139	    withPolicyWideModifiers(policyBasePremiumOf(items), policy) +
140	      itemSurchargesOf(items) +
141	      PROCESSING_FEE,
142	  );
143

